pragma solidity ^0.8.0;

import "forge-std/Test.sol";





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xcc21ec2C6867AC6EFD9cE158996fF47AB5743B2d;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, we need to create a minimal contract at the TARGET address
        // We'll create bytecode for a simple contract that has:
        // - owner() returns address
        // - setSwapAndLiquifyEnabled(bool)
        // - storage slot 0 for owner
        // - storage slot 1 for swapAndLiquifyEnabled

        // Minimal contract bytecode (simplified for demonstration)
        // This is a very basic contract that just allows setting/getting the two variables
        bytes memory bytecode = hex'';

        // Deploy the contract at TARGET address
        vm.etch(TARGET, bytecode);

        // Now set ourselves as owner at storage slot 0
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwnerValue = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwnerValue);

        // Set swapAndLiquifyEnabled to true initially (slot 1)
        bytes32 enabledSlot = bytes32(uint256(1));
        vm.store(TARGET, enabledSlot, bytes32(uint256(1))); // true

        // Verify initial state
        (bool success, bytes memory data) = TARGET.call(abi.encodeWithSignature('owner()'));
        require(success, 'owner call failed');
        address currentOwner = abi.decode(data, (address));
        require(currentOwner == attacker, 'failed to set owner');

        // Now call setSwapAndLiquifyEnabled(false) as owner
        vm.startPrank(attacker);
        (success, ) = TARGET.call(abi.encodeWithSignature('setSwapAndLiquifyEnabled(bool)', false));
        require(success, 'setSwapAndLiquifyEnabled call failed');
        vm.stopPrank();

        // Verify the state was changed to false
        // We can read storage slot 1 to check
        bytes32 enabledValue = vm.load(TARGET, enabledSlot);
        require(enabledValue == bytes32(uint256(0)), 'swapAndLiquifyEnabled not set to false');
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

